// Task представляет собой функцию, которая будет выполнена воркером.
// Контекст позволяет отменить выполнение задачи или установить таймаут.
type Task func(ctx context.Context) error

// WorkerPool реализует пул воркеров с ограничением параллелизма.
// Он принимает задачи из канала и распределяет их между фиксированным
// количеством воркеров.
type WorkerPool struct {
	// tasks — канал, из которого воркеры берут задачи для выполнения.
	tasks chan Task

	// wg — WaitGroup для ожидания завершения всех активных задач.
	wg sync.WaitGroup

	// ctx — контекст пула, который используется для отмены всех задач.
	ctx context.Context

	// cancel — функция отмены контекста пула.
	cancel context.CancelFunc

	// once — гарантирует, что Close() будет выполнен только один раз.
	once sync.Once

	// closed — флаг, указывающий, что пул закрыт и новые задачи не принимаются.
	closed bool

	// mu — мьютекс для защиты поля closed.
	mu sync.Mutex
}

// NewWorkerPool создаёт новый пул воркеров с указанным количеством воркеров.
// Параметры:
//   - ctx: родительский контекст, который будет использован для создания внутреннего контекста пула.
//   - numWorkers: количество воркеров (должно быть больше 0).
//   - bufferSize: размер буфера канала задач. Если 0, канал будет небуферизованным.
//
// Возвращает указатель на созданный пул.
func NewWorkerPool(ctx context.Context, numWorkers int, bufferSize int) *WorkerPool {
	// Создаём внутренний контекст с возможностью отмены, наследуя от переданного.
	poolCtx, cancel := context.WithCancel(ctx)

	// Создаём канал задач с указанным размером буфера.
	tasks := make(chan Task, bufferSize)

	pool := &WorkerPool{
		tasks:  tasks,
		ctx:    poolCtx,
		cancel: cancel,
	}

	// Запускаем указанное количество воркеров.
	for i := 0; i < numWorkers; i++ {
		pool.wg.Add(1)
		go pool.worker()
	}

	return pool
}

