import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.locks.ReentrantReadWriteLock;

/**
 * Потокобезопасный LRU-кэш с ограничением по памяти.
 * <p>
 * Кэш хранит пары ключ-значение и автоматически вытесняет наименее
 * недавно используемые записи при превышении лимита памяти.
 * <p>
 * Память оценивается как сумма размеров ключей и значений,
 * вычисленных через {@link #calculateSize(Object)}.
 * <p>
 * Для обеспечения потокобезопасности используется {@link ReentrantReadWriteLock}:
 * операции чтения (get) и записи (put) блокируют только на время
 * модификации внутренней структуры данных.
 *
 * @param <K> тип ключей
 * @param <V> тип значений
 */
public class LRUMemoryCache<K, V> {

    /**
     * Максимальный допустимый размер кэша в байтах.
     */
    private final long maxMemoryBytes;

    /**
     * Текущий суммарный размер всех записей в кэше в байтах.
     */
    private long currentMemoryBytes;

    /**
     * Хеш-таблица для быстрого доступа к узлам по ключу.
     * Значение — ссылка на узел двусвязного списка.
     */
    private final Map<K, Node<K, V>> map;

    /**
     * Голова двусвязного списка: содержит самый недавно использованный элемент.
     */
    private Node<K, V> head;

    /**
     * Хвост двусвязного списка: содержит самый давно использованный элемент.
     */
    private Node<K, V> tail;

    /**
     * Замок для обеспечения потокобезопасности.
     * Read lock используется для get, write lock — для put и remove.
     */
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    /**
     * Узел двусвязного списка, хранящий ключ, значение и размер записи.
     *
     * @param <K> тип ключа
     * @param <V> тип значения
     */
    private static class Node<K, V> {
        K key;
        V value;
        long size; // размер записи в байтах
        Node<K, V> prev;
        Node<K, V> next;

        Node(K key, V value, long size) {
