//! Парсер аргументов командной строки для утилиты сжатия файлов.
//!
//! Этот модуль предоставляет структуру `CliArgs`, которая хранит распарсенные
//! аргументы, и функцию `parse_args`, которая выполняет парсинг.

use std::env;
use std::path::PathBuf;

/// Структура, представляющая распарсенные аргументы командной строки.
#[derive(Debug, Clone)]
pub struct CliArgs {
    /// Путь к входному файлу или директории.
    pub input_path: PathBuf,
    /// Путь к выходному файлу.
    pub output_path: PathBuf,
    /// Уровень сжатия (от 1 до 9).
    pub compression_level: u8,
    /// Флаг: удалять ли исходный файл после успешного сжатия.
    pub delete_source: bool,
    /// Флаг: перезаписывать ли существующий выходной файл.
    pub overwrite: bool,
    /// Флаг: выводить подробную информацию о процессе сжатия.
    pub verbose: bool,
}

/// Ошибка парсинга аргументов командной строки.
#[derive(Debug)]
pub enum ParseError {
    /// Отсутствует обязательный аргумент.
    MissingArgument(String),
    /// Неверное значение аргумента.
    InvalidValue(String),
    /// Неизвестный флаг или опция.
    UnknownOption(String),
    /// Слишком много позиционных аргументов.
    TooManyArguments,
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ParseError::MissingArgument(arg) => write!(f, "Отсутствует обязательный аргумент: {}", arg),
            ParseError::InvalidValue(msg) => write!(f, "Неверное значение: {}", msg),
            ParseError::UnknownOption(opt) => write!(f, "Неизвестная опция: {}", opt),
            ParseError::TooManyArguments => write!(f, "Слишком много позиционных аргументов"),
        }
    }
}

impl std::error::Error for ParseError {}

