// Экспортируем функцию debounce, которая принимает функцию fn и задержку ms
// T — это обобщённый тип, ограниченный функцией, принимающей любые аргументы и возвращающей void
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера setTimeout
  // Инициализируется как undefined, чтобы показать, что таймер ещё не установлен
  let timer: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая будет выполнять дебаунсинг
  // Параметры этой функции совпадают с параметрами оригинальной функции fn
  return (...args: Parameters<T>) => {
    // Если таймер уже установлен (не undefined), отменяем предыдущий вызов
    // Это гарантирует, что fn будет вызвана только после последнего срабатывания
    if (timer) clearTimeout(timer);

    // Устанавливаем новый таймер на ms миллисекунд
    // По истечении этого времени будет вызвана оригинальная функция fn с переданными аргументами
    timer = setTimeout(() => fn(...args), ms);
  };
}
```

