// Get извлекает значение из кэша по указанному ключу.
//
// Метод потокобезопасен: использует блокировку на чтение (RLock) для доступа
// к внутреннему хранилищу элементов, что позволяет одновременное чтение
// несколькими горутинами.
//
// Поведение:
//   - Если ключ отсутствует в кэше, возвращается пустая строка и false.
//   - Если ключ найден, но срок действия записи истёк (текущее время позже
//     времени истечения expires), возвращается пустая строка и false.
//     Примечание: просроченные записи не удаляются автоматически при вызове
//     Get; они остаются в памяти до явного удаления или очистки.
//   - Если ключ найден и запись не просрочена, возвращается значение и true.
//
// Параметры:
//   - key: строковый ключ, по которому выполняется поиск в кэше.
//     Пустая строка допустима как ключ, если она была ранее добавлена.
//
// Возвращаемые значения:
//   - string: значение, связанное с ключом, если запись найдена и не просрочена;
//     пустая строка ("") в противном случае.
//   - bool: true, если запись найдена и действительна; false, если ключ отсутствует
//     или запись просрочена.
//
// Граничные случаи:
//   - Конкурентный доступ: несколько горутин могут одновременно вызывать Get
//     без взаимной блокировки благодаря RLock.
//   - Просроченные записи: метод проверяет срок действия на лету, но не выполняет
//     очистку. Для удаления просроченных записей необходимо использовать
//     отдельный механизм очистки (например, фоновый сборщик или явный вызов
//     метода удаления).
//   - Нулевое значение expires: если поле expires равно нулевому значению time.Time,
//     запись считается просроченной сразу (так как time.Now() всегда позже
//     нулевого времени).
//   - Отсутствие мьютекса: предполагается, что поле c.mu инициализировано
//     (например, через sync.RWMutex{} в конструкторе). Использование нулевого
//     значения sync.RWMutex допустимо, но требует осторожности.
//
// Пример использования:
//
//	value, found := cache.Get("user:123")
//	if found {
//	    fmt.Println("Значение:", value)
//	} else {
//	    fmt.Println("Запись не найдена или просрочена")
//	}
func (c *Cache) Get(key string) (string, bool) {
	c.mu.RLock()
	e, ok := c.items[key]
	c.mu.RUnlock()
	if !ok || time.Now().After(e.expires) {
		return "", false
	}
	return e.value, true
}
```

